<div class="content-wrapper" style="min-height: 916px;">    <!-- Content Header (Page header) -->    <section class="content-header">        <h1>Danh sách sản phẩm</h1>        <ol class="breadcrumb">            <li><a href="/<?php echo ADMIN_URL; ?>"><i class="fa fa-dashboard"></i> Home</a></li>            <li class="active">Danh Sách sản phẩm</li>        </ol>        <a href="/<?php echo ADMIN_URL; ?>product/add"><button style="width: 130px;float: left;margin-right: 10px;" class="btn btn-block btn-primary">Thêm sản phẩm</button></a>        <select class="form-control" id="cat_id" style="width: 150px;float: left;margin-right: 10px;">            <?php echo $category_html; ?>        </select>        <select class="form-control" id="order" style="width:  150px;float: left;margin-right: 10px;">            <option value=""> -- Sắp xếp -- </option>                        <option value="is_hot DESC">Sản phẩm hot</option>                                           </select>        <input class="form-control" id="title" placeholder="Nhập ID hoặc tên sp" style="width:  200px;float: left;margin-right: 10px;"/>        <button id="update_hot" style="width: 130px;float: left;margin-right: 10px;" class="btn btn-block btn-primary">Cập nhật</button>    </section>    <br/><br/>    <!-- Main content -->    <section class="content">        <div class="row">            <div class="col-xs-12">                <div class="box" id="list_ajax">                </div>            </div><!-- /.box -->        </div><!-- /.col -->    </section></div><!-- /.row --><style>    input[type="checkbox"]{height: 20px;width: 30px;}</style>   <script>    var current_pos = <?php echo $pos; ?>;    function loadlist(pos) {        current_pos = pos;        var cat_id = $('#cat_id').val();        var order = $('#order').val();        var title = $('#title').val();        $.post('/<?php echo ADMIN_URL; ?>product/page', {pos: pos, cat_id: cat_id, order: order, title: title}, function (results) {            $('#list_ajax').html(results);        });    }    $('#cat_id').change(function () {        loadlist(0);    });    $('#order').change(function () {        loadlist(0);    });    $("#title").keypress(function (e) {        if (e.keyCode == 13) {            loadlist(0);        }    });    loadlist(current_pos);    $('#list_ajax').on('click', '.pagination a', function () {        var pos = $(this).attr('href').replace('/', '');        loadlist(pos);        return false;    });    function del(id) {        show_dialog('Bạn có muốn xóa company id = ' + id + " không", function () {            $.post('/<?php echo ADMIN_URL; ?>product/del', {id: id}, function (results) {                loadlist(current_pos);            });        });    }    $("#update_hot").click(function () {        var update = [];        $(".is_hot").each(function () {            var val = $(this).is(':checked') ? 1 : 0;            var price = $(".price", $(this).parents('tr')).autoNumeric('get');            update.push({'is_hot': val, price: price, id: $(this).attr('rel')});        });        $.post('/<?php echo ADMIN_URL; ?>product/update_hot', {data: update}, function (results) {            loadlist(current_pos);        });    });</script>